    /// <summary>
    /// Similar to g_filename_to_uri(), but attempts to handle relative file paths
    /// as well. Before converting @filename into an URI, it will be prefixed by
    /// the current working directory if it is a relative path, and then the path
    /// will be canonicalised so that it doesn't contain any './' or '../' segments.
    /// </summary>
    /// <remarks>
    /// <para>On Windows @filename should be in UTF-8 encoding.</para>
    /// </remarks>
    /// <param name="filename">The <c>filename</c> argument.</param>
    /// <returns>
    /// newly-allocated URI string, or NULL on error. The caller must
    ///   free the URI string with g_free() when no longer needed.
    /// </returns>
    /// <exception cref="Gst.GLib.GException">The native call failed.</exception>
    public static string? FilenameToUri(string filename)
    {
        ArgumentNullException.ThrowIfNull(filename);
        System.Span<byte> filenameBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope filenameScope = Gst.Interop.GMarshal.StackUtf8(filename, filenameBuffer);
        nint errorNative = 0;
        nint nativeResult = GstFilenameToUri(filenameScope.Pointer, &errorNative);
        if (errorNative != 0 && nativeResult != 0)
        {
            // The call failed and transferred a value all the same. The throw
            // below puts it out of reach, so it is released rather than leaked.
            Gst.Interop.GMarshal.Free(nativeResult);
        }
        Gst.GLib.GException.ThrowIfSet(ref errorNative);
        return Gst.Interop.GMarshal.PtrToStringUtf8AndFree(nativeResult);
    }

