    /// <summary>
    /// Calculates the simpler representation of @numerator and @denominator and
    /// update both values with the resulting simplified fraction.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Simplify a fraction using a simple continued fraction decomposition.
    /// The idea here is to convert fractions such as 333333/10000000 to 1/30
    /// using 32 bit arithmetic only. The algorithm is not perfect and relies
    /// upon two arbitrary parameters to remove non-significative terms from
    /// the simple continued fraction decomposition. Using 8 and 333 for
    /// @n_terms and @threshold respectively seems to give nice results.
    /// </para>
    /// </remarks>
    /// <param name="numerator">The <c>numerator</c> argument.</param>
    /// <param name="denominator">The <c>denominator</c> argument.</param>
    /// <param name="nTerms">The <c>nTerms</c> argument.</param>
    /// <param name="threshold">The <c>threshold</c> argument.</param>
    public static void UtilSimplifyFraction(ref int numerator, ref int denominator, uint nTerms, uint threshold)
    {
        int numeratorNative = numerator;
        int denominatorNative = denominator;
        GstUtilSimplifyFraction(&numeratorNative, &denominatorNative, nTerms, threshold);
        numerator = numeratorNative;
        denominator = denominatorNative;
    }

