    /// <summary>Gets the version number of the GStreamer library.</summary>
    /// <param name="major">The <c>major</c> argument.</param>
    /// <param name="minor">The <c>minor</c> argument.</param>
    /// <param name="micro">The <c>micro</c> argument.</param>
    /// <param name="nano">The <c>nano</c> argument.</param>
    public static void Version(out uint major, out uint minor, out uint micro, out uint nano)
    {
        uint majorNative = default;
        uint minorNative = default;
        uint microNative = default;
        uint nanoNative = default;
        GstVersion(&majorNative, &minorNative, &microNative, &nanoNative);
        major = majorNative;
        minor = minorNative;
        micro = microNative;
        nano = nanoNative;
    }

    /// <summary>
    /// This function returns a string that is useful for describing this version
    /// of GStreamer to the outside world: user agent strings, logging, ...
    /// </summary>
    /// <returns>
    /// a newly allocated string describing this version
    ///     of GStreamer.
    /// </returns>
    public static string VersionString()
    {
        nint nativeResult = GstVersionString();
        return Gst.Interop.GMarshal.PtrToStringUtf8AndFree(nativeResult)
            ?? throw new InvalidOperationException("gst_version_string returned no value.");
    }

